create table RB_DOSS_TRAN_HIST (SEQ_NO VARCHAR(50) not null  ,CHANNEL_SEQ_NO VARCHAR(60) null  ,SUB_SEQ_NO VARCHAR(60) null  ,REFERENCE VARCHAR(60) null  ,CLIENT_NO VARCHAR(22) not null  ,INTERNAL_KEY INT not null  ,BASE_ACCT_NO VARCHAR(50) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,PROD_TYPE VARCHAR(20) null  ,ACCT_CCY VARCHAR(3) null  ,TRAN_DATE TIMESTAMP(3) null  ,TRAN_AMT DECIMAL(17,2) null  ,TRAN_STATUS VARCHAR(1) null  ,INT_IND_FLAG VARCHAR(1) null  ,ACCR_DATE TIMESTAMP(3) null  ,INT_ACCR DECIMAL(17,2) null  ,REMARK VARCHAR(200) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  , primary key(SEQ_NO,CLIENT_NO,INTERNAL_KEY));